    # map each type to its rounded average days_open
    pass

exercises.solution:
def avg_days_open_by_type(requests):
    sums, counts = {}, {}
    for r in requests:
        sums[r['type']] = sums.get(r['type'], 0) + r['days_open']
        counts[r['type']] = counts.get(r['type'], 0) + 1
    return {t: round(sums[t] / counts[t]) for t in sums}

exercises.starter:
def slowest_neighborhood(requests):
    # return the neighborhood with the greatest average days_open
    pass

exercises.solution:
def slowest_neighborhood(requests):
    sums, counts = {}, {}
    for r in requests:
        sums[r['neighborhood']] = sums.get(r['neighborhood'], 0) + r['days_open']
        counts[r['neighborhood']] = counts.get(r['neighborhood'], 0) + 1
    best, best_avg = None, float('-inf')
    for nb in sorted(sums):
        avg = sums[nb] / counts[nb]
        if avg > best_avg:
            best_avg, best = avg, nb
    return best

exercises.starter:
def busiest_type(requests):
    # return the most common request type
    pass

exercises.solution:
def busiest_type(requests):
    counts = {}
    for r in requests:
        counts[r['type']] = counts.get(r['type'], 0) + 1
    best, best_count = None, 0
    for t in sorted(counts):
        if counts[t] > best_count:
            best_count, best = counts[t], t
    return best
